def transform(grid):
    g=[row[:] for row in grid]
    pts={v:[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==v] for v in (7,9)}
    def bbox(p):
        rs=[x[0] for x in p]; cs=[x[1] for x in p]
        return min(rs),max(rs),min(cs),max(cs)
    a=bbox(pts[7]); b=bbox(pts[9])
    for r,c in pts[7]+pts[9]: g[r][c]=6
    for r in range(b[0],b[1]+1):
        for c in range(b[2],b[3]+1): g[r][c]=7
    ac=((a[0]+a[1])/2,(a[2]+a[3])/2); bc=((b[0]+b[1])/2,(b[2]+b[3])/2)
    if abs(bc[1]-ac[1])>abs(bc[0]-ac[0]):
        zc=sorted({c for r,row in enumerate(grid) for c,x in enumerate(row) if x==0 and min(ac[1],bc[1])<c<max(ac[1],bc[1])})[0]
        for r in range(a[0],a[1]+1): g[r][zc]=2
    else:
        zr=sorted({r for r,row in enumerate(grid) for c,x in enumerate(row) if x==0 and min(ac[0],bc[0])<r<max(ac[0],bc[0])})[0]
        for c in range(a[2],a[3]+1): g[zr][c]=2
    return g
